// Browser-safe identity data generated by `pnpm brand:generate`. It holds only
// literal kit values (no environment), so client components, next/og renderers
// and worker emails can all import it. Deployment identity stays in app.ts.
import geometry from "@/brand/exports/code/logo-geometry.json";
import tokens from "@/brand/exports/code/tokens.json";

export const brandGeometry = {
  viewBox: "0 0 108 108",
  /** The 100-unit artwork sits centered in the 108-unit symbol box. */
  offset: "translate(4 0)",
  left: geometry.left,
  microLeft: geometry.microLeft,
  rightTransform: geometry.rightTransform,
} as const;

/** The product the kit draws; the outlined wordmark only spells this name. */
export const kitName = geometry.wordmark.text;

export const brandPalette = tokens.palette;
export const brandThemes = tokens.themes;

/** Symbol colors per kit variant: [left path, right path]. */
export const markColors = {
  primary: [tokens.palette.poolTeal, tokens.palette.companionTeal],
  dark: [tokens.palette.paleTeal, tokens.palette.lightTeal],
  white: [tokens.palette.white, tokens.palette.white],
} as const;

/** Below this CSS size the kit prescribes the micro cut. */
export const fullSymbolMinPx = tokens.minimums.fullSymbolCssPx;

/** Runtime files under public/, served from each deployment's own origin. */
export const brandFiles = {
  favicon: "/favicon.ico",
  iconSvg: "/icon.svg",
  appleTouchIcon: "/apple-touch-icon.png",
  notificationIcon: "/brand/icons/notification-192.png",
  pwa: {
    any192: "/brand/icons/icon-any-192.png",
    any512: "/brand/icons/icon-any-512.png",
    maskable192: "/brand/icons/icon-maskable-192.png",
    maskable512: "/brand/icons/icon-maskable-512.png",
  },
  /** White lockup baked onto deep ink, 480×144 (3× of 160×48). Opaque so
   *  dark-mode mail clients cannot recolor it into the header band. */
  emailLogo: "/brand/email/logo-badge-480.png",
} as const;
